export type JobStatus = "queued" | "running" | "complete" | "failed";

export type Speaker =
  | "user"
  | "planner"
  | "search"
  | "structure"
  | "design"
  | "reviewer"
  | "system";

export type Message = {
  id: string;
  speaker: Speaker;
  body: string;
  stage: string | null;
  artifact_ids: string[];
  created_at: string;
};

export type ArtifactInfo = {
  id: string;
  filename: string;
  media_type: string;
  bytes: number;
  stage: string;
  title: string;
  purpose: string;
};

export type JobEvent = {
  id: number;
  type: string;
  stage: string | null;
  message: string;
  artifact_id: string | null;
  created_at: string;
};

